<?php
declare(strict_types=1);
namespace App\Http\Controllers\Api\V1\Admin;
use App\Core\{Request,Response,TenantContext};use App\Domain\Authorization\AuthorizationService;use App\Domain\Reports\ScopedAnalyticsService;
final class AnalyticsController {public function __construct(private ScopedAnalyticsService $service,private AuthorizationService $auth){}public function dashboard(Request$r):Response{$c=TenantContext::get();$this->auth->requirePermission($c,'dashboard','view');return Response::json(200,$this->service->dashboard($c));}public function report(Request$r):Response{$c=TenantContext::get();$key=(string)$r->param('key');$module=['lead-source'=>'leads','response-time'=>'leads','conversion'=>'leads','sales-team-productivity'=>'internalUsers','territory-sales'=>'orders','party-sales'=>'orders','product-sales'=>'orders','scheme-utilization'=>'schemes','order-status'=>'orders','dispatch-pending'=>'dispatch','batch-inventory'=>'inventory','near-expiry'=>'nearExpiry','territory-violations'=>'territory','webhook-failures'=>'webhooks','whatsapp-delivery'=>'notifications'][$key]??'reports';$this->auth->requirePermission($c,$module,'view');return Response::json(200,$this->service->report($c,$key,$r->query));}}
